begin;
select no_plan();

-- AR-001--005, 112, 130--136, 145, 150, 154--155: exact boundary and catalog.
select has_table('bios_knowledge','document_representations','AR-001 Representation table exists');
select has_table('bios_knowledge','processing_runs','AR-002 Processing Run table exists');
select results_eq($$select count(*)::bigint from pg_tables where schemaname='bios_knowledge' and tablename in ('document_representations','processing_runs')$$,array[2::bigint],'AR-003 exactly two M007 tables');
select results_eq($$select (select count(*) from bios_knowledge.document_representations)+(select count(*) from bios_knowledge.processing_runs)$$,array[0::bigint],'AR-004/145 zero production seeds');
select is_empty($$select 1 from information_schema.tables where table_schema like 'bios_%' and table_name in ('representation_types','representation_lineage','representation_segments','representation_chunks','processing_run_outputs','processing_run_inputs','model_registries','provider_registries','pipeline_registries','prompt_registries','entitlements','trusted_readers','access_grants','embeddings','vectors')$$,'AR-005/112/130--136 deferred structures absent');
select is_empty($$select 1 from information_schema.columns where table_schema='bios_knowledge' and table_name='processing_runs' and column_name='output_representation_id'$$,'AR-068 sole output relation is reverse producing_run_id');
select results_eq($$select count(*)::bigint from pg_indexes where schemaname='bios_knowledge' and tablename in ('document_representations','processing_runs')$$,array[12::bigint],'AR-150 required indexes installed');
select results_eq($$select count(*)::bigint from pg_constraint where conrelid in ('bios_knowledge.document_representations'::regclass,'bios_knowledge.processing_runs'::regclass) and contype='f'$$,array[9::bigint],'AR-006--013/044 relational lineage and Tenant/Language FKs');

-- Synthetic active foundation fixtures.
insert into bios_core.tenants(id,code,name,status,activated_at) values
 ('c7000000-0000-0000-0000-000000000001','representation_tenant_a','Representation Tenant A','active',statement_timestamp()),
 ('c7000000-0000-0000-0000-000000000002','representation_tenant_b','Representation Tenant B','active',statement_timestamp());
insert into bios_core.languages(id,tag,base_language_subtag,display_name,status,activated_at) values
 ('c7100000-0000-0000-0000-000000000001','rxa','rxa','Representation Language A','active',statement_timestamp()),
 ('c7100000-0000-0000-0000-000000000002','rxb','rxb','Representation Language B','active',statement_timestamp());
insert into bios_knowledge.sources(id,code,canonical_name,knowledge_scope,status,activated_at) values
 ('c7200000-0000-0000-0000-000000000001','representation_shared','Representation Shared','shared','active',statement_timestamp());
insert into bios_knowledge.sources(id,code,canonical_name,knowledge_scope,tenant_id,status,activated_at) values
 ('c7200000-0000-0000-0000-000000000002','representation_private','Representation Private','tenant','c7000000-0000-0000-0000-000000000001','active',statement_timestamp());
insert into bios_knowledge.source_documents(id,source_id,knowledge_scope,tenant_id,canonical_title,language_mode,language_id,access_classification) values
 ('c7300000-0000-0000-0000-000000000001','c7200000-0000-0000-0000-000000000001','shared',null,'Public single','single','c7100000-0000-0000-0000-000000000001','public'),
 ('c7300000-0000-0000-0000-000000000002','c7200000-0000-0000-0000-000000000001','shared',null,'Licensed','single','c7100000-0000-0000-0000-000000000001','licensed'),
 ('c7300000-0000-0000-0000-000000000003','c7200000-0000-0000-0000-000000000001','shared',null,'Restricted','single','c7100000-0000-0000-0000-000000000001','restricted'),
 ('c7300000-0000-0000-0000-000000000004','c7200000-0000-0000-0000-000000000002','tenant','c7000000-0000-0000-0000-000000000001','Private A','single','c7100000-0000-0000-0000-000000000001','tenant_confidential');
update bios_knowledge.source_documents set status='active',activated_at=statement_timestamp() where id::text like 'c7300000-%';
select set_config('request.jwt.claims','{"role":"service_role"}',true);

-- AR-014--043, 056--066: bounded vocabularies, input, context, and parameters.
select throws_ok($$insert into bios_knowledge.processing_runs(input_source_document_id,input_representation_id,knowledge_scope,operation_kind,processor_identifier,processor_version,actor_identifier,correlation_id,purpose) values('c7300000-0000-0000-0000-000000000001',gen_random_uuid(),'shared','extract_text','p','1','a','c','p')$$,'23514',null,'AR-014 exactly one input');
select throws_ok($$select bios_internal.start_processing_run('c7300000-0000-0000-0000-000000000001',null,'shared',null,'normalize','processor','1',null,null,'{}','actor','corr-map','purpose')$$,'P0001','operation requires Representation input','AR-015/041 direct operation mapping');
select throws_ok($$select bios_internal.start_processing_run('c7300000-0000-0000-0000-000000000001',null,'shared',null,'invalid','processor','1',null,null,'{}','actor','corr-op','purpose')$$,'P0001',null,'AR-040 exact operation vocabulary');
select throws_ok($$insert into bios_knowledge.processing_runs(input_source_document_id,knowledge_scope,operation_kind,processor_identifier,processor_version,parameters,actor_identifier,correlation_id,purpose) values('c7300000-0000-0000-0000-000000000001','shared','extract_text','p','1','[]','a','c','p')$$,'23514',null,'AR-056 parameters object only');
select throws_ok($$insert into bios_knowledge.processing_runs(input_source_document_id,knowledge_scope,operation_kind,processor_identifier,processor_version,parameters,actor_identifier,correlation_id,purpose) values('c7300000-0000-0000-0000-000000000001','shared','extract_text','p','1','{"token":"x"}','a','c','p')$$,'23514',null,'AR-057 secrets prohibited in parameters');
select throws_ok($$insert into bios_knowledge.processing_runs(input_source_document_id,knowledge_scope,operation_kind,processor_identifier,processor_version,parameters,actor_identifier,correlation_id,purpose) values('c7300000-0000-0000-0000-000000000001','shared','extract_text','p','1',jsonb_build_object('GoodKey',1),'a','c','p')$$,'23514',null,'AR-058 lowercase stable parameter keys');
select throws_ok($$insert into bios_knowledge.processing_runs(input_source_document_id,knowledge_scope,operation_kind,processor_identifier,processor_version,actor_identifier,correlation_id,purpose) values('c7300000-0000-0000-0000-000000000001','shared','extract_text',' ','1','a','c','p')$$,'23514',null,'AR-052 processor identity bounded');
select throws_ok($$select bios_internal.start_processing_run('c7300000-0000-0000-0000-000000000001',null,'shared',null,'extract_text','processor','1',null,null,'{}',null,'corr','purpose')$$,'P0001',null,'AR-060--064 governed context required and non-authorizing');

-- AR-091--112: authorization matrix and trusted start.
select lives_ok($$select bios_internal.start_processing_run('c7300000-0000-0000-0000-000000000001',null,'shared',null,'extract_text','processor','1',null,null,'{"mode":"plain"}','actor','corr-shared','public extraction')$$,'AR-091 shared/public to shared starts');
select results_eq($$select outcome from bios_knowledge.processing_runs where correlation_id='corr-shared'$$,array['running'],'AR-065/066 new Run is running with null terminal fields');
select lives_ok($$select bios_internal.start_processing_run('c7300000-0000-0000-0000-000000000001',null,'tenant','c7000000-0000-0000-0000-000000000001','ocr','processor','1',null,null,'{}','actor','corr-narrow','governed tenant derivation')$$,'AR-092--096 shared/public to active target Tenant starts only trusted');
select lives_ok($$select bios_internal.start_processing_run('c7300000-0000-0000-0000-000000000004',null,'tenant','c7000000-0000-0000-0000-000000000001','transcribe','processor','1',null,null,'{}','actor','corr-private','same tenant')$$,'AR-097--100 same-Tenant private starts');
select throws_ok($$select bios_internal.start_processing_run('c7300000-0000-0000-0000-000000000004',null,'tenant','c7000000-0000-0000-0000-000000000002','extract_text','processor','1',null,null,'{}','actor','corr-cross','purpose')$$,'P0001','same-Tenant tenant-confidential processing required','AR-101 cross-Tenant rejected');
select throws_ok($$select bios_internal.start_processing_run('c7300000-0000-0000-0000-000000000004',null,'shared',null,'extract_text','processor','1',null,null,'{}','actor','corr-broaden','purpose')$$,'P0001','same-Tenant tenant-confidential processing required','AR-102 private to shared rejected');
select throws_ok($$select bios_internal.start_processing_run('c7300000-0000-0000-0000-000000000002',null,'shared',null,'extract_text','processor','1',null,null,'{}','actor','corr-license','purpose')$$,'P0001','shared licensed or restricted processing is not authorized','AR-103--106/110/111 licensed rejected despite context');
select throws_ok($$select bios_internal.start_processing_run('c7300000-0000-0000-0000-000000000003',null,'tenant','c7000000-0000-0000-0000-000000000001','extract_text','processor','1','model','1','{"mode":"x"}','actor','corr-restrict','purpose')$$,'P0001','shared licensed or restricted processing is not authorized','AR-107--111 restricted rejected despite service context');

-- AR-016--039, 044--051, 067--080: atomic output, content, digest and lineage.
select lives_ok($$select bios_internal.complete_processing_run_success((select id from bios_knowledge.processing_runs where correlation_id='corr-shared'),'c7100000-0000-0000-0000-000000000001','text/plain','same hash',encode(digest('same hash','sha256'),'hex'),'public',null,'actor','corr-complete','complete')$$,'AR-067 successful completion atomically creates output');
select results_eq($$select outcome from bios_knowledge.processing_runs where correlation_id='corr-shared'$$,array['succeeded'],'AR-067--069 Run succeeds with one reverse output');
select results_eq($$select status from bios_knowledge.document_representations where producing_run_id=(select id from bios_knowledge.processing_runs where correlation_id='corr-shared')$$,array['candidate'],'AR-075 output born candidate');
select throws_ok($$update bios_knowledge.document_representations set content_text='rewrite' where producing_run_id=(select id from bios_knowledge.processing_runs where correlation_id='corr-shared')$$,'P0001','Representation material and lineage are immutable','AR-016--032/077 material and lineage immutable');
select throws_ok($$insert into bios_knowledge.document_representations(source_document_id,producing_run_id,knowledge_scope,representation_kind,language_id,media_type,content_text,content_sha256,access_classification) values('c7300000-0000-0000-0000-000000000001',(select id from bios_knowledge.processing_runs where correlation_id='corr-narrow'),'shared','extracted_text','c7100000-0000-0000-0000-000000000001','application/json','x',encode(digest('x','sha256'),'hex'),'public')$$,'23514',null,'AR-026 exact media rejects JSON');
select throws_ok($$insert into bios_knowledge.document_representations(source_document_id,producing_run_id,knowledge_scope,representation_kind,language_id,media_type,content_text,content_sha256,access_classification) values('c7300000-0000-0000-0000-000000000001',(select id from bios_knowledge.processing_runs where correlation_id='corr-narrow'),'shared','extracted_text','c7100000-0000-0000-0000-000000000001','text/plain','x',repeat('0',64),'public')$$,'23514',null,'AR-030--035 verified SHA-256 required');
select throws_ok($$select bios_internal.complete_processing_run_success((select id from bios_knowledge.processing_runs where correlation_id='corr-narrow'),'c7100000-0000-0000-0000-000000000002','text/plain','wrong language',encode(digest('wrong language','sha256'),'hex'),'tenant_confidential',null,'actor','corr-lang','complete')$$,'P0001','direct output Language must match Source Document','AR-044--048 direct Language semantics');
select lives_ok($$select bios_internal.complete_processing_run_success((select id from bios_knowledge.processing_runs where correlation_id='corr-narrow'),'c7100000-0000-0000-0000-000000000001','text/markdown','same hash',encode(digest('same hash','sha256'),'hex'),'tenant_confidential',null,'actor','corr-narrow-complete','complete')$$,'AR-033 duplicate hash permitted with distinct identity');
select results_eq($$select count(*)::bigint from bios_knowledge.document_representations where content_sha256=encode(digest('same hash','sha256'),'hex')$$,array[2::bigint],'AR-032--035 hash nonunique and not identity');
select lives_ok($$select bios_internal.complete_processing_run_terminal((select id from bios_knowledge.processing_runs where correlation_id='corr-private'),'failed','processor_error','safe summary','actor','corr-failed','failed')$$,'AR-070 failed Run transition');
select results_eq($$select count(*)::bigint from bios_knowledge.document_representations where producing_run_id=(select id from bios_knowledge.processing_runs where correlation_id='corr-private')$$,array[0::bigint],'AR-070 failed Run has zero output');
select throws_ok($$update bios_knowledge.processing_runs set error_summary='changed' where correlation_id='corr-private'$$,'P0001','terminal Processing Run is immutable','AR-072 terminal Run immutable');

-- AR-151--153 oversized output fails without content alteration or output.
select lives_ok($$select bios_internal.start_processing_run('c7300000-0000-0000-0000-000000000001',null,'shared',null,'extract_text','processor','1',null,null,'{}','actor','corr-large','size test')$$,'AR-151 oversized test Run starts');
select is(bios_internal.complete_processing_run_success((select id from bios_knowledge.processing_runs where correlation_id='corr-large'),'c7100000-0000-0000-0000-000000000001','text/plain',repeat('x',1048577),encode(digest(repeat('x',1048577),'sha256'),'hex'),'public',null,'actor','corr-large-complete','size test'),null::uuid,'AR-151 oversized completion returns no Representation');
select results_eq($$select outcome||':'||error_code from bios_knowledge.processing_runs where correlation_id='corr-large'$$,array['failed:content_too_large'],'AR-151 exact content_too_large failure');
select results_eq($$select count(*)::bigint from bios_knowledge.document_representations r join bios_knowledge.processing_runs p on p.id=r.producing_run_id where p.correlation_id='corr-large'$$,array[0::bigint],'AR-151/152 no truncation, splitting, or output workaround');

-- AR-073--090: activation, transformations, translation, and supersession.
select lives_ok($$select bios_internal.transition_document_representation((select id from bios_knowledge.document_representations where producing_run_id=(select id from bios_knowledge.processing_runs where correlation_id='corr-shared')),'active','actor','corr-active','activate')$$,'AR-076/079 candidate activates after revalidation');
select lives_ok($$select bios_internal.start_processing_run(null,(select id from bios_knowledge.document_representations where status='active' and knowledge_scope='shared'),'shared',null,'normalize','processor','1',null,null,'{}','actor','corr-normalize','normalize')$$,'AR-041 Representation-input normalization starts');
select lives_ok($$select bios_internal.complete_processing_run_success((select id from bios_knowledge.processing_runs where correlation_id='corr-normalize'),'c7100000-0000-0000-0000-000000000001','text/plain','normalized',encode(digest('normalized','sha256'),'hex'),'public',null,'actor','corr-normalize-complete','complete')$$,'AR-041/046 normalization preserves parent Language and lineage');
select lives_ok($$select bios_internal.start_processing_run(null,(select id from bios_knowledge.document_representations where status='active' and knowledge_scope='shared'),'shared',null,'translate','processor','1',null,null,'{}','actor','corr-translate','translate')$$,'AR-041 Representation-input translation starts');
select throws_ok($$select bios_internal.complete_processing_run_success((select id from bios_knowledge.processing_runs where correlation_id='corr-translate'),'c7100000-0000-0000-0000-000000000001','text/plain','translation',encode(digest('translation','sha256'),'hex'),'public',null,'actor','corr-translate-bad','complete')$$,'P0001','translation Language must differ from parent','AR-047 translation requires different Language');
select lives_ok($$select bios_internal.complete_processing_run_success((select id from bios_knowledge.processing_runs where correlation_id='corr-translate'),'c7100000-0000-0000-0000-000000000002','text/html','translation',encode(digest('translation','sha256'),'hex'),'public',null,'actor','corr-translate-complete','complete')$$,'AR-047/048 translation records child Language on one-parent chain');
select lives_ok($$select bios_internal.start_processing_run('c7300000-0000-0000-0000-000000000001',null,'shared',null,'extract_text','processor','2',null,null,'{}','actor','corr-successor','correction')$$,'AR-081 correction requires a new Run');
select lives_ok($$select bios_internal.complete_processing_run_success((select id from bios_knowledge.processing_runs where correlation_id='corr-successor'),'c7100000-0000-0000-0000-000000000001','text/plain','corrected',encode(digest('corrected','sha256'),'hex'),'public',(select id from bios_knowledge.document_representations where status='active' and representation_kind='extracted_text'),'actor','corr-successor-complete','complete')$$,'AR-081--088 compatible candidate successor created');
select lives_ok($$select bios_internal.transition_document_representation((select id from bios_knowledge.document_representations where content_text='corrected'),'active','actor','corr-successor-active','activate correction')$$,'AR-083--090 deterministic atomic supersession');
select results_eq($$select status from bios_knowledge.document_representations where content_text in ('same hash','corrected') and knowledge_scope='shared' order by content_text$$,array['active','superseded'],'AR-084 predecessor superseded and successor active');

-- AR-113--144: RLS, privileges, audit, preservation and Evidence boundary.
select results_eq($$select count(*)::bigint from pg_policies where schemaname='bios_knowledge' and tablename in ('document_representations','processing_runs')$$,array[1::bigint],'AR-113/119 Representation read policy only; no ordinary Run read');
select ok(not has_table_privilege('anon','bios_knowledge.document_representations','select') and not has_table_privilege('anon','bios_knowledge.processing_runs','select'),'AR-114 anonymous reads denied');
select ok(not has_table_privilege('authenticated','bios_knowledge.processing_runs','select') and has_table_privilege('authenticated','bios_knowledge.document_representations','select'),'AR-117--119 ordinary Run hidden; governed Representation select granted');
select ok(not has_table_privilege('authenticated','bios_knowledge.document_representations','insert') and not has_table_privilege('authenticated','bios_knowledge.document_representations','update') and not has_table_privilege('authenticated','bios_knowledge.processing_runs','insert'),'AR-115 ordinary direct mutation denied');
select ok(not has_function_privilege('authenticated','bios_internal.start_processing_run(uuid,uuid,text,uuid,text,text,text,text,text,jsonb,text,text,text)','execute') and has_function_privilege('service_role','bios_internal.start_processing_run(uuid,uuid,text,uuid,text,text,text,text,text,jsonb,text,text,text)','execute'),'AR-116/122 trusted-only execution');
select results_eq($$select count(*)::bigint from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='bios_internal' and p.proname in ('start_processing_run','complete_processing_run_success','complete_processing_run_terminal','transition_document_representation') and p.prosecdef and p.proconfig=array['search_path=""']$$,array[4::bigint],'AR-120--123 hardened SECURITY DEFINER functions');
select throws_ok($$delete from bios_knowledge.document_representations where content_text='normalized'$$,'P0001','Representation foundation rows cannot be deleted','AR-078 physical deletion denied');
select results_eq($$select count(*)::bigint from bios_governance.audit_events where resource_type in ('document_representation','processing_run') and action not in ('reference.created','reference.status_changed')$$,array[0::bigint],'AR-124--129 approved audit vocabulary only');
select is_empty($$select 1 from bios_governance.audit_events where resource_type in ('document_representation','processing_run') and (metadata ? 'content_text' or metadata ? 'parameters' or metadata ? 'prompt' or metadata ? 'token' or metadata ? 'secret' or octet_length(metadata::text)>8192)$$,'AR-127--129 safe bounded audit metadata excludes content/secrets');
select results_eq($$select count(*)::bigint from bios_governance.audit_events where resource_type='document_representation' and action='reference.created' and resource_id in (select id from bios_knowledge.document_representations)$$,array[5::bigint],'AR-124/125 successful Representation creation audited exactly');
select ok(to_regclass('bios_knowledge.evidence') is not null and to_regclass('bios_knowledge.evidence_provenance') is not null,'AR-137 DB-007 tables structurally retained');
select is_empty($$select 1 from information_schema.columns where table_schema='bios_knowledge' and table_name in ('evidence','evidence_provenance') and column_name in ('representation_id','processing_run_id')$$,'AR-138--144 no Evidence integration or automated activation');

select * from finish();
rollback;
